class Controller:
    def __init__(self,s):
        self.s=s
        self.m=s.model
        self.ids=np.array([self.m.joint(f'robot0_joint{i}').id for i in range(1,8)])
        self.qi=self.m.jnt_qposadr[self.ids]
        self.vi=self.m.jnt_dofadr[self.ids]
        self.limits=self.m.jnt_range[self.ids]
        self.sid=self.m.site('gripper0_right_grip_site').id
        self.ikdata=mujoco.MjData(self.m)
    def pos(self): return self.s.data.site_xpos[self.sid].copy()
    def ori(self): return self.s.data.site_xmat[self.sid].reshape(3,3).copy()
    def obj(self,name): return self.s.data.xpos[self.m.body(name+'_main').id].copy()
    def ik(self,pos,ori,q=None):
        d=self.ikdata
        d.qpos[:]=self.s.data.qpos
        if q is not None: d.qpos[self.qi]=q
        jp=np.zeros((3,self.m.nv)); jr=jp.copy()
        for i in range(160):
            mujoco.mj_fwdPosition(self.m,d)
            err=np.r_[np.asarray(pos)-d.site_xpos[self.sid],Rot.from_matrix(ori@d.site_xmat[self.sid].reshape(3,3).T).as_rotvec()]
            if np.linalg.norm(err)<1e-5: break
            mujoco.mj_jacSite(self.m,d,jp,jr,self.sid)
            J=np.vstack([jp[:,self.vi],jr[:,self.vi]])
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*0.0001,err)
            dq*=min(1,0.15/max(np.max(np.abs(dq)),1e-6))
            d.qpos[self.qi]=np.clip(d.qpos[self.qi]+dq,self.limits[:,0]+.001,self.limits[:,1]-.001)
        if np.linalg.norm(err)>.015: print('IK error',np.round(err,3),flush=True)
        return d.qpos[self.qi].copy()
    def joint(self,q,n=50,grip=None):
        a=self.s.hold_targets(); start=self.s.data.qpos[self.qi].copy()
        if grip is not None:a[7]=grip
        for t in range(n):
            u=(t+1)/n; u=u*u*(3-2*u)
            a[:7]=start+(q-start)*u
            self.s.step(a)
    def hold(self,n=20,grip=None):
        a=self.s.hold_targets()
        if grip is not None:a[7]=grip
        for _ in range(n):self.s.step(a)
    def move(self,pos,ori=None,n=60,grip=None):
        if ori is None:ori=self.ori()
        self.joint(self.ik(pos,ori),n,grip)
        self.hold(6)
        print('move',len(self.s.actions),'eef',np.round(self.pos(),3),flush=True)
    def line(self,pos,ori=None,n=50,grip=None):
        if ori is None:ori=self.ori()
        p0=self.pos(); q=self.s.data.qpos[self.qi].copy(); a=self.s.hold_targets()
        if grip is not None:a[7]=grip
        for t in range(n):
            u=(t+1)/n
            q=self.ik(p0+(np.array(pos)-p0)*u,ori,q)
            a[:7]=q; self.s.step(a)
        self.hold(6)
        print('line',len(self.s.actions),'eef',np.round(self.pos(),3),'spray',np.round(self.obj('spray'),3),flush=True)
    def base(self,v,n=30,torso=0):
        a=self.s.hold_targets(); a[8:11]=v;a[11]=torso;a[12]=1
        for _ in range(n):self.s.step(a)
        self.hold(10)
        print('base',self.s.data.xpos[self.m.body('robot0_link0').id],flush=True)
    def snap(self,name='view'):
        Image.fromarray(self.s.render_grid()).save('/app/output/'+name+'.png')
    def status(self):
        print(self.s.check(), 'eef',self.pos(), 'objects',[(n,self.obj(n)) for n in ['spray','dish_brush','cutting_board']],flush=True)
